    zh_TW: `這不會修改雲端資料。之後必須重新填入可解密雲端資料的密碼，才能繼續同步。`,
    ja: `クラウドデータは変更されません。再同期するには、クラウドデータを復号できるパスフレーズを再入力する必要があります。`,
    ko: `클라우드 데이터는 변경되지 않습니다. 다시 동기화하려면 클라우드 데이터를 해독할 수 있는 암호문을 입력해야 합니다.`,
